class NodeDetailsView extends ConsumerStatefulWidget {
  const NodeDetailsView({
    super.key,
    required this.coin,
    required this.nodeId,
    required this.popRouteName,
  });

  static const String routeName = "/nodeDetails";

  final CryptoCurrency coin;
  final String nodeId;
  final String popRouteName;

  @override
  ConsumerState<NodeDetailsView> createState() => _NodeDetailsViewState();
}

class _NodeDetailsViewState extends ConsumerState<NodeDetailsView> {
  late final SecureStorageInterface secureStore;
  late final CryptoCurrency coin;
  late final String nodeId;
  late final String popRouteName;

  bool _desktopReadOnly = true;
  bool _busy = false;
  late final NodeFormData _form;

  VoidCallback? _whileIdle(Future<void> Function() action) =>
      _busy ? null : () => _runBusy(action);

  Future<void> _runBusy(Future<void> Function() action) async {
    if (_busy) return;
    setState(() => _busy = true);
    try {
      await WidgetsBinding.instance.endOfFrame;
      await _form.passwordLoad;
      if (mounted) await action();
    } catch (error, stack) {
      Logging.instance.w('$error', error: error, stackTrace: stack);
      if (mounted) {
        unawaited(
          showFloatingFlushBar(
            type: FlushBarType.warning,
            message: 'Node operation failed',
            context: context,
          ),
        );
      }
    } finally {
      if (mounted) setState(() => _busy = false);
    }
  }

  @override
  initState() {
    _form = ref.refresh(nodeFormDataProvider);
    secureStore = ref.read(secureStoreProvider);
    coin = widget.coin;
    nodeId = widget.nodeId;
    popRouteName = widget.popRouteName;
    super.initState();
  }

  @override
  Widget build(BuildContext context) {
    final isDesktop = Util.isDesktop;

    final node = ref.watch(
      nodeServiceChangeNotifierProvider.select(
        (value) => value.getNodeById(id: nodeId),
      ),
    );

    final nodesForCoin = ref.watch(
      nodeServiceChangeNotifierProvider.select(
        (value) => value.getNodesFor(coin),
      ),
    );

    final canDelete = nodesForCoin.length > 1;

    return ConditionalParent(
      condition: !isDesktop,
      builder: (child) => Background(
        child: Scaffold(
          backgroundColor: Theme.of(context)
              .extension<StackColors>()!
              .background,
          appBar: AppBar(
            leading: AppBarBackButton(
              onPressed: () async {
                if (FocusScope.of(context).hasFocus) {
                  FocusScope.of(context).unfocus();
                  await Future<void>.delayed(const Duration(milliseconds: 75));
                }
                if (context.mounted) {
                  Navigator.of(context).pop();
                }
              },
            ),
            title: Text(
              "Node details",
              style: STextStyles.navBarTitle(context),
            ),
            actions: [
              // if (!nodeId.startsWith(DefaultNodes.defaultNodeIdPrefix))
              Padding(
                padding: const EdgeInsets.only(top: 10, bottom: 10, right: 10),
                child: AspectRatio(
                  aspectRatio: 1,
                  child: AppBarIconButton(
                    key: const Key("nodeDetailsEditNodeAppBarButtonKey"),
                    size: 36,
                    shadows: const [],
                    color: Theme.of(context)
                        .extension<StackColors>()!
                        .background,
                    icon: SvgPicture.asset(
                      Assets.svg.pencil,
                      color: Theme.of(context)
                          .extension<StackColors>()!
                          .accentColorDark,
                      width: 20,
                      height: 20,
                    ),
                    onPressed: _busy
                        ? null
                        : () {
                            Navigator.of(context).pushNamed(
                              AddEditNodeView.routeName,
                              arguments: Tuple4(
                                AddEditNodeViewType.edit,
                                coin,
                                nodeId,
                                popRouteName,
                              ),
                            );
                          },
                  ),
                ),
              ),
            ],
          ),
          body: SafeArea(
            child: Padding(
              padding: const EdgeInsets.only(top: 12, left: 12, right: 12),
              child: LayoutBuilder(
                builder: (context, constraints) {
                  return SingleChildScrollView(
                    child: Padding(
                      padding: const EdgeInsets.all(4),
                      child: ConstrainedBox(
                        constraints: BoxConstraints(
                          minHeight: constraints.maxHeight - 8,
                        ),
                        child: IntrinsicHeight(child: child),
                      ),
                    ),
                  );
                },
              ),
            ),
          ),
        ),
      ),
      child: ConditionalParent(
        condition: isDesktop,
        builder: (child) => DesktopDialog(
          maxWidth: 580,
          maxHeight: double.infinity,
          child: Column(
            mainAxisSize: MainAxisSize.min,
            children: [
              Row(
                children: [
                  const SizedBox(width: 8),
                  const AppBarBackButton(iconSize: 24, size: 40),
                  Text("Node details", style: STextStyles.desktopH3(context)),
                ],
              ),
              Padding(
                padding: const EdgeInsets.only(
                  left: 32,
                  right: 32,
                  top: 16,
                  bottom: 32,
                ),
                child: child,
              ),
            ],
          ),
        ),
        child: Column(
          crossAxisAlignment: CrossAxisAlignment.stretch,
          children: [
            NodeForm(
              // Reload the form only when the stored node changes.
              key: ValueKey(node),
              data: _form,
              busy: _busy,
              node: node,
              secureStore: secureStore,
              readOnly: isDesktop ? _desktopReadOnly : true,
              coin: coin,
            ),
            if (!isDesktop) const Spacer(),
            if (isDesktop) const SizedBox(height: 22),
            if (isDesktop && canDelete)
              SizedBox(
                height: 56,
                child: _desktopReadOnly
                    ? null
                    : Row(
                        children: [
                          Expanded(
                            child: DeleteButton(
                              label: "Delete node",
                              desktopMed: true,
                              onPressed: _busy
                                  ? null
                                  : () async {
                                      final service = ref.read(
                                        nodeServiceChangeNotifierProvider,
                                      );
                                      Navigator.of(context).pop();

                                      await service.delete(node!.id, true);
                                    },
                            ),
                          ),
                          const SizedBox(width: 16),
                          const Spacer(),
                        ],
                      ),
              ),
            if (isDesktop && !_desktopReadOnly && canDelete)
              const SizedBox(height: 45),
            Row(
              children: [
                Expanded(
                  child: SecondaryButton(
                    label: "Test connection",
                    enabled: !_busy,
                    buttonHeight: isDesktop ? ButtonHeight.l : null,
                    onPressed: _whileIdle(() async {
                      final service = ref.read(
                        nodeServiceChangeNotifierProvider,
                      );
                      final notify = nodeChangeNotifier(ref, coin);
                      final node = ref
                          .read(nodeServiceChangeNotifierProvider)
                          .getNodeById(id: nodeId)!;

                      final editing = isDesktop && !_desktopReadOnly;
                      final nodeFormData = editing
                          ? _form
                          : NodeFormData.fromNode(node);
                      if (!editing) {
                        nodeFormData.password = await node.getPassword(
                          ref.read(secureStoreProvider),
                        );
                      }

                      if (context.mounted) {
                        final testPassed =
                            await ref.read(testNodeConnectionProvider)(
                              context: context,
                              nodeFormData: nodeFormData,
                              cryptoCurrency: coin,
                            );

                        if (testPassed) {
                          if (!editing) {
                            final saved = await service.saveTrustedCertificate(
                              node,
                              nodeFormData,
                            );
                            if (saved) await notify();
                          }
                          if (mounted) setState(() {});
                          if (context.mounted) {
                            unawaited(
                              showFloatingFlushBar(
                                type: FlushBarType.success,
                                message: "Server ping success",
                                context: context,
                              ),
                            );
                          }
                        } else {
                          if (context.mounted) {
                            unawaited(
                              showFloatingFlushBar(
                                type: FlushBarType.warning,
                                message: "Server unreachable",
                                context: context,
                              ),
                            );
                          }
                        }
                      }
                    }),
                  ),
                ),
                if (isDesktop) const SizedBox(width: 16),
                if (isDesktop)
                  Expanded(
                    child: PrimaryButton(
                      label: _desktopReadOnly ? "Edit" : "Save",
                      enabled: !_busy,
                      buttonHeight: ButtonHeight.l,
                      onPressed: _whileIdle(() async {
                        if (_desktopReadOnly) {
                          setState(() => _desktopReadOnly = false);
                          return;
                        }
                        final service = ref.read(
                          nodeServiceChangeNotifierProvider,
                        );
                        final notify = nodeChangeNotifier(ref, coin);
                        final editedNode = node!.copyWith(
                          host: _form.host,
                          port: _form.port,
                          name: _form.name,
                          useSSL: _form.useSSL,
                          trusted: _form.trusted,
                          trustedCertificatePem: _form.trustedCertificatePem,
                          clearTrustedCertificate:
                              _form.trustedCertificatePem == null,
                          loginName: _form.login,
                          isFailover: _form.isFailover,
                          torEnabled:
                              _form.netOption == TorPlainNetworkOption.tor ||
                              _form.netOption == TorPlainNetworkOption.both,
                          clearnetEnabled:
                              _form.netOption == TorPlainNetworkOption.clear ||
                              _form.netOption == TorPlainNetworkOption.both,
                          forceNoTor: _form.forceNoTor,
                        );

                        if (!await service.saveEdit(
                          editedNode,
                          _form.password,
                          true,
                          opened: _form.source!,
                          forgetCertificate: _form.certificateForgotten,
                        )) {
                          return;
                        }
                        await notify();
                        if (mounted) setState(() => _desktopReadOnly = true);
                      }),
                    ),
                  ),
              ],
            ),
            if (!isDesktop) const SizedBox(height: 16),
          ],
        ),
      ),
    );
  }
}
